import type { ScopeRequest1 } from "./generated/request.js";
import type { Facts } from "./io.js";
import type { Decision } from "./rules/runner.js";

/**
 * The signed assertion of what the sensor saw: a compact JWS
 * (ES256, `kid = <install_id>:<assertion_key_version>`, `typ: scope-observer+jwt`) on the hop to
 * the origin, signed with a key the customer holds (generated by `init`, never Scope's), so the
 * origin can verify the facts it is handed against Scope's directory of install public keys.
 */
export const ASSERTION_HEADER = "x-scope-assertion";
export const AGENT_HEADER = "x-scope-agent";
export const ASSERTION_TYP = "scope-observer+jwt";
export const ASSERTION_TTL_SECONDS = 300;

export interface AgentName {
  name: string;
  /** How the sensor named the agent: a verified signature, a declared header or MCP client, or the reader family. */
  named_by: "verified" | "declared" | "inferred";
}

export interface AssertionClaims {
  iss: string;
  aud: string;
  iat: number;
  exp: number;
  jti: string;
  record: string;
  reader: string;
  agent: AgentName;
  signature: { valid: boolean; agent: string } | null;
  decisions: Array<{ rule: string; outcome: string }>;
  address_hash: string;
  salt_epoch: number;
  policy_version: number;
}

/** The sensor's own name for the agent, labelled with how it was named; never the stitcher's. */
export function agentName(record: ScopeRequest1): AgentName {
  const signature = record["scope.signature"];
  if (signature?.valid) return { name: signature.agent, named_by: "verified" };
  const declared = record["scope.key.agent_header"] ?? record["scope.mcp.client"]?.name ?? null;
  if (declared) return { name: declared, named_by: "declared" };
  return { name: record["scope.reader"], named_by: "inferred" };
}

export function assertionClaims(record: ScopeRequest1, decisions: readonly Decision[], issuer: string, audience: string, nowMs: number): AssertionClaims {
  const iat = Math.floor(nowMs / 1000);
  const signature = record["scope.signature"];
  return {
    iss: issuer,
    aud: audience,
    iat,
    exp: iat + ASSERTION_TTL_SECONDS,
    jti: record.id,
    record: record.id,
    reader: record["scope.reader"],
    agent: agentName(record),
    signature: signature ? { valid: signature.valid, agent: signature.agent } : null,
    decisions: decisions.map((d) => ({ rule: d.rule, outcome: d.outcome })),
    address_hash: record["scope.client.address_hash"],
    salt_epoch: record.observer.salt_epoch,
    policy_version: record.observer.policy_version,
  };
}

const encoder = new TextEncoder();
export const base64url = (bytes: Uint8Array): string => btoa(String.fromCharCode(...bytes)).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/, "");

/** The compact JWS: ES256 over the header and the claims, the signature in the raw r||s form JWS requires, which WebCrypto produces. */
export async function signAssertion(claims: AssertionClaims, key: CryptoKey, kid: string): Promise<string> {
  const header = base64url(encoder.encode(JSON.stringify({ alg: "ES256", kid, typ: ASSERTION_TYP })));
  const payload = base64url(encoder.encode(JSON.stringify(claims)));
  const signature = await crypto.subtle.sign({ name: "ECDSA", hash: "SHA-256" }, key, encoder.encode(`${header}.${payload}`));
  return `${header}.${payload}.${base64url(new Uint8Array(signature))}`;
}

/** The private JWK (P-256, `d` present) as a signing key; the adapters import it once per isolate. */
export function importAssertionKey(jwk: JsonWebKey): Promise<CryptoKey> {
  return crypto.subtle.importKey("jwk", jwk, { name: "ECDSA", namedCurve: "P-256" }, false, ["sign"]);
}

const imported = new Map<string, Promise<Facts["assertion"]>>();

/**
 * `JOURNEYS_ASSERTION_KEY` as the adapters read it: the private JWK `init` wrote, carrying its
 * `kid`. Absent or malformed means no key: the headers are omitted and the decision log says so.
 */
export function assertionFromEnv(value: string | undefined, issuer: string | null): Promise<Facts["assertion"]> {
  if (!value || !issuer) return Promise.resolve(null);
  const memo = `${issuer}\n${value}`;
  let pending = imported.get(memo);
  if (!pending) {
    pending = (async (): Promise<Facts["assertion"]> => {
      try {
        const jwk = JSON.parse(value) as JsonWebKey & { kid?: string };
        if (jwk.kty !== "EC" || jwk.crv !== "P-256" || typeof jwk.d !== "string" || typeof jwk.kid !== "string") return null;
        const { kid, ...key } = jwk;
        return { kid, key: await importAssertionKey(key), issuer };
      } catch {
        return null;
      }
    })();
    imported.set(memo, pending);
  }
  return pending;
}

/** For the tests: forget the imported keys. */
export function resetAssertionKeys(): void {
  imported.clear();
}
